(()=>{'use strict';
const C=window.FranklinAssistantCore;if(!C)return;
const VERSION='FR-NAV1.29.3-HF3.10.3';
const ANSWERS={
 permit:['A permit may be required depending on the project, property and location. Identify the exact work and address first, then confirm the requirement with the City of Franklin permit or planning source before work begins.','Puede requerirse un permiso según el proyecto, la propiedad y la ubicación. Identifique el trabajo y la dirección exactos y confirme el requisito con la fuente oficial de permisos o planificación de la Ciudad antes de comenzar.'],
 school:['Franklin addresses can fall under different school systems and attendance zones. The reliable answer depends on the exact address, so confirm it with the responsible district or official school-zone source before enrolling or planning transportation.','Las direcciones de Franklin pueden corresponder a distintos sistemas y zonas escolares. La respuesta confiable depende de la dirección exacta; confírmela con el distrito o la fuente oficial de zona antes de inscribirse o planificar transporte.'],
 transport:['Franklin-area transportation includes fixed-route, accessible and other mobility options. The best fit depends on pickup area, mobility needs and schedule; I can use Franklin information first and check current service details when needed.','El transporte del área de Franklin incluye rutas fijas, servicios accesibles y otras opciones de movilidad. La mejor opción depende del área, las necesidades y el horario; puedo usar primero la información de Franklin y verificar detalles actuales cuando sea necesario.'],
 senior:['For an older adult or caregiver, it helps to separate the need into transportation, health care, daily support, benefits and safety. I can answer one part or connect several parts into one plan.','Para una persona mayor o cuidador conviene separar la necesidad en transporte, atención médica, apoyo diario, beneficios y seguridad. Puedo responder una parte o conectar varias en un solo plan.'],
 health:['For non-emergency health questions, I can help find local care options, prepare for a visit, compare public profile information and organize questions. Changing clinical, insurance or availability details should be checked against current sources.','Para preguntas de salud que no sean de emergencia, puedo ayudar a encontrar opciones locales, prepararse para una visita, comparar perfiles públicos y organizar preguntas. Los datos clínicos, de seguro o disponibilidad que cambian deben verificarse con fuentes actuales.'],
 legal:['I can help organize the issue, identify the responsible court or agency, prepare questions and find local legal-service profiles. Franklin Assistant does not replace a lawyer or calculate legal deadlines, so deadline-sensitive facts should be confirmed at the official source.','Puedo ayudar a organizar el asunto, identificar el tribunal o agencia responsable, preparar preguntas y encontrar perfiles legales locales. Franklin Assistant no sustituye a un abogado ni calcula plazos; los datos sensibles a plazos deben confirmarse en la fuente oficial.'],
 housing:['Housing help depends on whether the issue is rent, eviction risk, affordability, utilities, property records or a homeowner problem. Tell me which is happening and I can give the most relevant Franklin answer and next steps.','La ayuda de vivienda depende de si se trata de alquiler, riesgo de desalojo, asequibilidad, servicios, registros de propiedad o un problema del propietario. Dígame cuál ocurre y le daré la respuesta y próximos pasos más útiles.'],
 'food-benefits':['If you need food or benefits help, I can separate immediate food access from SNAP or other benefit questions and then check the current responsible source when eligibility or hours may have changed.','Si necesita ayuda con alimentos o beneficios, puedo separar el acceso inmediato a alimentos de SNAP u otros beneficios y verificar la fuente responsable cuando la elegibilidad u horarios puedan haber cambiado.'],
 'business-start':['A practical Franklin business-start sequence is: confirm the location and zoning, identify required registrations or licenses, check permits that apply, then set up your public presence and local growth plan.','Una secuencia práctica para iniciar un negocio en Franklin es: confirmar ubicación y zonificación, identificar registros o licencias, revisar permisos aplicables y luego establecer su presencia pública y plan de crecimiento local.'],
 'business-growth':['Start with one measurable local goal—more calls, appointments, visits or repeat customers—then check how your public profile appears, improve verified contact/action links and use a focused local growth plan.','Empiece con una meta local medible—más llamadas, citas, visitas o clientes recurrentes—revise cómo aparece su perfil público, mejore enlaces verificados de contacto/acción y use un plan de crecimiento local.'],
 jobs:['I can help identify Franklin-area job and internship starting points, local employers and a practical application or training plan. For live openings I will check current sources.','Puedo ayudar a identificar empleos y pasantías del área de Franklin, empleadores locales y un plan de solicitud o capacitación. Para vacantes actuales verificaré fuentes vigentes.'],
 events:['Event details change quickly. I will use Franklin Navigator’s dated local information first and check current web sources when the date, time, ticket status or availability needs a fresh answer.','Los detalles de eventos cambian rápidamente. Usaré primero la información local fechada de Franklin Navigator y consultaré fuentes web actuales cuando la fecha, hora, entradas o disponibilidad necesiten una respuesta fresca.'],
 sports:['I can help with Franklin-area leagues, teams, clinics, facilities and registration. Tell me the sport, age group and whether you want youth, adult or recreational options.','Puedo ayudar con ligas, equipos, clínicas, instalaciones e inscripción del área de Franklin. Dígame el deporte, grupo de edad y si busca opciones juveniles, adultas o recreativas.'],
 arts:['I can help find Franklin-area performances, classes, venues, auditions and community arts groups. For dates, tickets or current registration I will verify the latest source.','Puedo ayudar a encontrar espectáculos, clases, lugares, audiciones y grupos artísticos del área de Franklin. Para fechas, entradas o inscripción actual verificaré la fuente más reciente.'],
 parks:['I can help with Franklin parks, trails, recreation and outdoor activities. For closures, weather-sensitive access or current hours I will check a fresh source.','Puedo ayudar con parques, senderos, recreación y actividades al aire libre de Franklin. Para cierres, acceso sensible al clima u horarios actuales consultaré una fuente fresca.'],
 utilities:['Utility setup depends on the exact address and service type. I can help identify the responsible water, electric, sewer or internet starting point and check current contact details.','La configuración de servicios depende de la dirección y el tipo de servicio. Puedo ayudar a identificar el punto de partida para agua, electricidad, alcantarillado o internet y verificar datos de contacto actuales.'],
 sanitation:['Inside Franklin city limits, trash, recycling, brush and bulk-pickup details should be checked against the City’s current sanitation information, especially schedules and holiday changes.','Dentro de los límites de Franklin, los detalles de basura, reciclaje, ramas y recolección voluminosa deben verificarse con la información actual de saneamiento de la Ciudad, especialmente horarios y cambios por feriados.'],
 childcare:['I can help find local child-care profiles and licensed-care starting points, then verify current availability and requirements with the provider or responsible state source.','Puedo ayudar a encontrar perfiles locales de cuidado infantil y puntos de partida de cuidado con licencia, y verificar disponibilidad y requisitos con el proveedor o la fuente estatal responsable.'],
 civic:['I can help with Franklin wards, meetings, voting, development activity and public participation. Agendas, dates and election details change, so I will check the current official source when needed.','Puedo ayudar con distritos, reuniones, votación, desarrollo y participación pública de Franklin. Las agendas, fechas y datos electorales cambian, así que verificaré la fuente oficial actual cuando sea necesario.'],
 property:['Property questions often split into records, taxes, zoning, permits, HOA matters and notices. Tell me what document or issue you have and I can identify the right Franklin or Williamson County information.','Las preguntas de propiedad suelen dividirse en registros, impuestos, zonificación, permisos, HOA y avisos. Dígame qué documento o problema tiene y puedo identificar la información correcta de Franklin o Williamson County.'],
 auto:['For a vehicle issue, I can separate immediate safety, crash steps, recalls, repair, towing, buying and registration questions, then find local options or official sources as needed.','Para un problema de vehículo, puedo separar seguridad inmediata, pasos tras un choque, retiros, reparación, remolque, compra y registro, y luego encontrar opciones locales o fuentes oficiales.'],
 pets:['I can help find Franklin-area veterinary, boarding, grooming and other pet-service profiles, then verify current availability when needed.','Puedo ayudar a encontrar perfiles de veterinarios, hospedaje, peluquería y otros servicios para mascotas del área de Franklin, y verificar disponibilidad actual cuando sea necesario.'],
 membership:['Franklin Navigator Community Membership is optional and costs $35 per year. Paying does not change factual accuracy or ordinary Directory ranking. Existing members should use their current account rather than pay again.','La Membresía Comunitaria de Franklin Navigator es opcional y cuesta $35 al año. Pagar no cambia la exactitud factual ni la clasificación ordinaria del Directorio. Los miembros existentes deben usar su cuenta actual.'],
 profile:['Public profile corrections and removal requests are free. Membership is separate from factual accuracy and ordinary Directory placement.','Las correcciones y solicitudes de eliminación de perfiles públicos son gratuitas. La membresía es independiente de la exactitud factual y de la ubicación ordinaria en el Directorio.']
};
const L=id=>ANSWERS[id]||null;
function direct(raw,lang='en'){const m=C.mode(raw),es=lang==='es';if(m==='emergency')return{title:es?'Obtenga ayuda urgente ahora':'Get urgent help now',text:es?'Si alguien puede estar en peligro inmediato, llame al 911 ahora. Franklin Navigator no envía servicios de emergencia.':'If someone may be in immediate danger, call 911 now. Franklin Navigator does not dispatch responders.',confidence:'high'};if(m==='crisis')return{title:es?'Apoyo en crisis':'Crisis support',text:es?'Llame o envíe un mensaje al 988. Use el 911 si hay peligro inmediato.':'Call or text 988. Use 911 for immediate danger.',confidence:'high'};if(m==='billing')return{title:es?'Membresía y facturación':'Membership and billing',text:es?'Use su cuenta existente para administrar el método de pago o cancelar la renovación. Si un pago está procesándose o ya pagó, no vuelva a pagar.':'Use your existing account to manage the payment method or cancel renewal. If a payment is processing or you already paid, do not pay again.',confidence:'high'};const ids=C.concepts(raw);if(ids.length===1&&L(ids[0]))return{title:es?'Respuesta de Franklin Navigator':'Franklin Navigator answer',text:L(ids[0])[es?1:0],confidence:'medium',topics:ids};if(ids.length>1){const parts=ids.slice(0,3).map(id=>L(id)?.[es?1:0]).filter(Boolean);if(parts.length)return{title:es?'Cómo abordar las partes de su pregunta':'How to handle the parts of your question',text:parts.join(' '),confidence:'medium',topics:ids.slice(0,3)}}if(C.serviceFor(raw))return{title:es?'Opciones locales':'Local options',text:es?'Puedo mostrar perfiles públicos locales que coincidan con el servicio solicitado y las formas de contacto disponibles.':'I can show matching local public profiles and the available ways to contact them.',confidence:'medium'};return null}
function researchNeeded(raw,confidence='low'){const t=C.norm(raw);if(/\b(today|tonight|tomorrow|weekend|current|currently|latest|open now|hours|schedule|price|cost|available|availability|weather|closure|closed|deadline|meeting|agenda|election|results|news|hoy|esta noche|manana|fin de semana|actual|ultim|abierto ahora|horario|precio|costo|disponible|clima|cierre|fecha limite|reunion|agenda|eleccion|noticias)\b/.test(t))return true;return confidence==='low'}
function cleanRouteHits(hits){return(hits||[]).filter(x=>!String(x?.rec?.p||'').includes('/founding-member-planner/'))}
window.FranklinAssistantR1293Core=Object.freeze({VERSION,direct,researchNeeded,cleanRouteHits});
})();
